<?php
declare(strict_types=1);
require_once __DIR__.'/../../app/bootstrap.php';
require_once __DIR__.'/../../app/Modules/RestaurantCMS/helpers.php';
cms_require_admin();
$pdo=db();$notice='';$error='';$tab=preg_replace('/[^a-z-]/','',$_GET['tab']??'dashboard');
try{
if($_SERVER['REQUEST_METHOD']==='POST'){
    if(!hash_equals(csrf_token(),(string)($_POST['csrf']??'')))throw new RuntimeException('Güvenlik doğrulaması başarısız.');
    $action=(string)($_POST['action']??'');
    if($action==='save_block'){
        $id=(int)($_POST['id']??0);$data=[trim((string)$_POST['block_key']),trim((string)$_POST['block_type']),trim((string)$_POST['title']),trim((string)$_POST['subtitle']),trim((string)$_POST['body']),trim((string)$_POST['media_url']),trim((string)$_POST['button_text']),trim((string)$_POST['button_url']),trim((string)$_POST['background_color']),trim((string)$_POST['text_color']),isset($_POST['is_active'])?1:0,(int)$_POST['sort_order']];
        if($data[0]==='')$data[0]='block-'.bin2hex(random_bytes(4));
        if($id){$q=$pdo->prepare("UPDATE cms_content_blocks SET block_key=?,block_type=?,title=?,subtitle=?,body=?,media_url=?,button_text=?,button_url=?,background_color=?,text_color=?,is_active=?,sort_order=?,updated_at=NOW() WHERE id=? AND publish_scope='draft'");$q->execute([...$data,$id]);}
        else{$q=$pdo->prepare("INSERT INTO cms_content_blocks(block_key,block_type,title,subtitle,body,media_url,button_text,button_url,background_color,text_color,is_active,sort_order,publish_scope,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?, 'draft',NOW(),NOW())");$q->execute($data);} $notice='İçerik bloğu kaydedildi.';
    } elseif($action==='delete_block'){$q=$pdo->prepare("DELETE FROM cms_content_blocks WHERE id=? AND publish_scope='draft'");$q->execute([(int)$_POST['id']]);$notice='İçerik bloğu silindi.';
    } elseif($action==='duplicate_block'){$q=$pdo->prepare("INSERT INTO cms_content_blocks(block_key,block_type,title,subtitle,body,media_url,button_text,button_url,background_color,text_color,is_active,sort_order,publish_scope,created_at,updated_at) SELECT CONCAT(block_key,'-kopya-',SUBSTRING(MD5(RAND()),1,6)),block_type,CONCAT(COALESCE(title,block_key),' (Kopya)'),subtitle,body,media_url,button_text,button_url,background_color,text_color,is_active,sort_order+1,'draft',NOW(),NOW() FROM cms_content_blocks WHERE id=? AND publish_scope='draft'");$q->execute([(int)$_POST['id']]);$notice='İçerik bloğu çoğaltıldı.';
    } elseif($action==='save_order'){foreach((array)($_POST['order']??[]) as $i=>$id){$pdo->prepare("UPDATE cms_content_blocks SET sort_order=?,updated_at=NOW() WHERE id=? AND publish_scope='draft'")->execute([($i+1)*10,(int)$id]);}$notice='Blok sıralaması kaydedildi.';
    } elseif($action==='publish'){cms_publish($pdo);$notice='Taslak içerikler canlı menüye yayınlandı.';
    } elseif($action==='save_seo'){foreach(['seo_title','seo_description','seo_canonical','og_image','seo_robots'] as $k)cms_save_setting($k,trim((string)($_POST[$k]??'')),$pdo);$notice='SEO ayarları kaydedildi.';
    } elseif($action==='add_media'){$name=trim((string)($_POST['media_name']??''));$type=trim((string)($_POST['media_type']??'image'));$url=cms_safe_url((string)($_POST['media_url']??''));if(isset($_FILES['media_file'])&&($_FILES['media_file']['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_NO_FILE){$up=cms_upload_media($_FILES['media_file']);$url=$up['url'];$type=$up['type'];if($name==='')$name=$up['name'];}if($name===''||$url==='')throw new RuntimeException('Medya adı ve geçerli dosya/URL gereklidir.');$q=$pdo->prepare('INSERT INTO cms_media_library(media_name,media_type,media_url,alt_text,created_at) VALUES(?,?,?,?,NOW())');$q->execute([$name,$type,$url,trim((string)($_POST['alt_text']??''))]);$notice='Medya kaydı eklendi.';
    } elseif($action==='delete_media'){$pdo->prepare('DELETE FROM cms_media_library WHERE id=?')->execute([(int)$_POST['id']]);$notice='Medya kaydı silindi.';
    } elseif($action==='bulk_prices'){$mode=(string)$_POST['mode'];$value=(float)str_replace(',','.',(string)$_POST['value']);if($mode==='percent'){$factor=1+($value/100);$pdo->prepare('UPDATE products SET price=ROUND(price*?,2) WHERE is_active=1')->execute([$factor]);}else{$pdo->prepare('UPDATE products SET price=ROUND(price+?,2) WHERE is_active=1')->execute([$value]);}$notice='Aktif ürün fiyatları toplu güncellendi.';audit_log('cms_bulk_price_update','Toplu fiyat güncellemesi uygulandı.');}
}
}catch(Throwable $e){$error=$e->getMessage();app_log($e,['restaurant_cms'=>true]);}
$draft=cms_blocks('draft',false,$pdo);$published=cms_blocks('published',false,$pdo);$media=cms_media($pdo);$edit=null;if(isset($_GET['edit'])){foreach($draft as $b)if((int)$b['id']===(int)$_GET['edit'])$edit=$b;}
function h($v){return e((string)$v);} 
?><!doctype html><html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Restaurant CMS</title><style>body{margin:0;background:#f4f6f8;color:#172033;font-family:Inter,Arial,sans-serif}.wrap{max-width:1180px;margin:auto;padding:24px}.top{display:flex;justify-content:space-between;align-items:center;gap:12px}.nav{display:flex;gap:8px;flex-wrap:wrap;margin:18px 0}.nav a,.btn,button{border:0;border-radius:10px;padding:11px 14px;background:#111827;color:#fff;text-decoration:none;font-weight:700;cursor:pointer}.nav a.active{background:#d71920}.grid{display:grid;grid-template-columns:1fr 1fr;gap:18px}.card{background:#fff;border-radius:18px;padding:20px;box-shadow:0 12px 35px #0000000c;margin-bottom:18px}label{display:block;font-weight:700;margin:12px 0 5px}input,textarea,select{width:100%;box-sizing:border-box;padding:11px;border:1px solid #d8dee8;border-radius:10px;font:inherit}textarea{min-height:100px}.ok{background:#dcfce7;color:#166534;padding:12px;border-radius:10px}.err{background:#fee2e2;color:#991b1b;padding:12px;border-radius:10px}table{width:100%;border-collapse:collapse}th,td{text-align:left;padding:10px;border-bottom:1px solid #edf0f4}.muted{color:#64748b}.actions{display:flex;gap:7px;flex-wrap:wrap}.danger{background:#991b1b}.metric{font-size:34px;font-weight:900}.sortable tr{cursor:grab}.sortable tr.dragging{opacity:.45}.thumb{width:64px;height:48px;border-radius:8px;object-fit:cover;background:#eef2f7}.secondary{background:#475569}@media(max-width:800px){.grid{grid-template-columns:1fr}.wrap{padding:14px}}</style><link rel="stylesheet" href="/admin/enterprise/assets/media-picker.css?v=720"></head><body><div class="wrap"><div class="top"><div><h1>Restaurant CMS</h1><p class="muted">Menü içeriği, medya, SEO ve toplu ürün işlemleri.</p></div><a class="btn" href="/admin/qr-experience-v2/">QR Experience</a></div><?php if($notice):?><p class="ok"><?=h($notice)?></p><?php endif;if($error):?><p class="err"><?=h($error)?></p><?php endif;?><nav class="nav"><?php foreach(['dashboard'=>'Genel Bakış','content'=>'İçerik Blokları','menu'=>'Toplu Menü','media'=>'Medya','seo'=>'SEO'] as $k=>$v):?><a class="<?=$tab===$k?'active':''?>" href="?tab=<?=$k?>"><?=$v?></a><?php endforeach;?></nav>
<?php if($tab==='dashboard'):?><div class="grid"><div class="card"><div class="muted">Taslak blok</div><div class="metric"><?=count($draft)?></div></div><div class="card"><div class="muted">Yayındaki blok</div><div class="metric"><?=count($published)?></div></div><div class="card"><div class="muted">Medya kaydı</div><div class="metric"><?=count($media)?></div></div><div class="card"><h2>Yayınlama</h2><p>Taslak içerik bloklarını canlı QR menüye aktarır.</p><p class="muted">Son yayın: <?=h(cms_setting('last_published_at','Henüz yayınlanmadı',$pdo))?></p><p><a class="btn secondary" target="_blank" href="/admin/restaurant-cms/preview.php">Taslağı Önizle</a></p><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="publish"><button>Şimdi Yayınla</button></form></div></div>
<?php elseif($tab==='content'):?><div class="grid"><section class="card"><h2><?=$edit?'Bloğu Düzenle':'Yeni İçerik Bloğu'?></h2><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="save_block"><input type="hidden" name="id" value="<?=h($edit['id']??0)?>"><label>Blok anahtarı<input name="block_key" value="<?=h($edit['block_key']??'')?>" placeholder="hikayemiz"></label><label>Tür<select name="block_type"><?php foreach(['text'=>'Metin','image'=>'Görsel','banner'=>'Banner','quote'=>'Alıntı'] as $k=>$v):?><option value="<?=$k?>" <?=($edit['block_type']??'text')===$k?'selected':''?>><?=$v?></option><?php endforeach;?></select></label><label>Başlık<input name="title" value="<?=h($edit['title']??'')?>"></label><label>Alt başlık<input name="subtitle" value="<?=h($edit['subtitle']??'')?>"></label><label>Metin<textarea name="body"><?=h($edit['body']??'')?></textarea></label><label>Medya URL<input name="media_url" value="<?=h($edit['media_url']??'')?>"></label><label>Buton metni<input name="button_text" value="<?=h($edit['button_text']??'')?>"></label><label>Buton bağlantısı<input name="button_url" value="<?=h($edit['button_url']??'')?>"></label><div class="grid"><label>Arka plan<input type="color" name="background_color" value="<?=h($edit['background_color']??'#ffffff')?>"></label><label>Metin rengi<input type="color" name="text_color" value="<?=h($edit['text_color']??'#111827')?>"></label></div><label>Sıra<input type="number" name="sort_order" value="<?=h($edit['sort_order']??10)?>"></label><label><input style="width:auto" type="checkbox" name="is_active" value="1" <?=!isset($edit['is_active'])||$edit['is_active']?'checked':''?>> Aktif</label><button>Kaydet</button></form></section><section class="card"><h2>Taslak Bloklar</h2><p class="muted">Satırları sürükleyerek sırala ve ardından kaydet.</p><form method="post" id="orderForm"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="save_order"><table class="sortable" id="sortable"><tr><th>Başlık</th><th>Tür</th><th></th></tr><?php foreach($draft as $b):?><tr draggable="true" data-id="<?=(int)$b['id']?>"><td>↕ <?=h($b['title']?:$b['block_key'])?></td><td><?=h($b['block_type'])?></td><td><div class="actions"><a class="btn" href="?tab=content&edit=<?=(int)$b['id']?>">Düzenle</a><button type="submit" form="dup-<?=(int)$b['id']?>" class="secondary">Çoğalt</button><button type="submit" form="del-<?=(int)$b['id']?>" class="danger">Sil</button></div></td></tr><?php endforeach;?></table><div id="orderInputs"></div><button style="margin-top:12px">Sıralamayı Kaydet</button></form><?php foreach($draft as $b):?><form id="dup-<?=(int)$b['id']?>" method="post"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="duplicate_block"><input type="hidden" name="id" value="<?=(int)$b['id']?>"></form><form id="del-<?=(int)$b['id']?>" method="post" onsubmit="return confirm('Silinsin mi?')"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="delete_block"><input type="hidden" name="id" value="<?=(int)$b['id']?>"></form><?php endforeach;?></section></div>
<?php elseif($tab==='menu'):?><section class="card"><h2>Toplu Fiyat Güncelleme</h2><p class="muted">Yalnızca aktif ürünlere uygulanır. İşlemden önce veritabanı yedeği alın.</p><form method="post" onsubmit="return confirm('Aktif ürün fiyatları güncellensin mi?')"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="bulk_prices"><label>İşlem<select name="mode"><option value="percent">Yüzde ekle/çıkar</option><option value="fixed">Sabit tutar ekle/çıkar</option></select></label><label>Değer<input type="number" step="0.01" name="value" required placeholder="Örn. 10 veya -5"></label><button>Fiyatları Güncelle</button></form></section>
<?php elseif($tab==='media'):?><div class="grid"><section class="card"><h2>Medya Ekle</h2><form method="post" enctype="multipart/form-data"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="add_media"><label>Ad<input name="media_name" required></label><label>Tür<select name="media_type"><option>image</option><option>video</option><option>svg</option><option>pdf</option></select></label><label>Dosya yükle<input type="file" name="media_file" accept="image/jpeg,image/png,image/webp,image/gif,video/mp4,application/pdf"></label><p class="muted">veya</p><label>Harici URL<input name="media_url"></label><label>Alternatif metin<input name="alt_text"></label><button>Medya Kaydet</button></form></section><section class="card"><h2>Kütüphane</h2><table><tr><th>Önizleme</th><th>Ad</th><th>Tür</th><th></th></tr><?php foreach($media as $m):?><tr><td><?php if($m['media_type']==='image'):?><img class="thumb" src="<?=h($m['media_url'])?>" alt=""><?php else:?><span class="muted">Dosya</span><?php endif;?></td><td><a href="<?=h($m['media_url'])?>" target="_blank" rel="noopener"><?=h($m['media_name'])?></a></td><td><?=h($m['media_type'])?></td><td><form method="post" onsubmit="return confirm('Silinsin mi?')"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="delete_media"><input type="hidden" name="id" value="<?=(int)$m['id']?>"><button class="danger">Sil</button></form></td></tr><?php endforeach;?></table></section></div>
<?php elseif($tab==='seo'):?><section class="card"><h2>QR Menü SEO</h2><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="save_seo"><label>Sayfa başlığı<input name="seo_title" value="<?=h(cms_setting('seo_title',setting('business_name','Restoran').' · Menü',$pdo))?>"></label><label>Açıklama<textarea name="seo_description"><?=h(cms_setting('seo_description',setting('qr_seo_description','Menümüzü keşfedin.'),$pdo))?></textarea></label><label>Canonical URL<input name="seo_canonical" value="<?=h(cms_setting('seo_canonical','',$pdo))?>"></label><label>OpenGraph görseli<input name="og_image" value="<?=h(cms_setting('og_image','',$pdo))?>"></label><label>Arama motoru talimatı<select name="seo_robots"><option value="index,follow" <?=cms_setting('seo_robots','index,follow',$pdo)==='index,follow'?'selected':''?>>index, follow</option><option value="noindex,nofollow" <?=cms_setting('seo_robots','index,follow',$pdo)==='noindex,nofollow'?'selected':''?>>noindex, nofollow</option></select></label><button>SEO Ayarlarını Kaydet</button></form></section><?php endif;?></div><script>const t=document.getElementById('sortable');if(t){let d=null;t.querySelectorAll('tr[draggable]').forEach(r=>{r.addEventListener('dragstart',()=>{d=r;r.classList.add('dragging')});r.addEventListener('dragend',()=>r.classList.remove('dragging'));r.addEventListener('dragover',e=>{e.preventDefault();if(!d||d===r)return;const box=r.getBoundingClientRect();r.parentNode.insertBefore(d,e.clientY<box.top+box.height/2?r:r.nextSibling)})});document.getElementById('orderForm').addEventListener('submit',()=>{const w=document.getElementById('orderInputs');w.innerHTML='';t.querySelectorAll('tr[data-id]').forEach(r=>{const i=document.createElement('input');i.type='hidden';i.name='order[]';i.value=r.dataset.id;w.appendChild(i)})})}</script><script src="/admin/enterprise/assets/media-picker.js?v=720"></script></body></html>
